from abc import ABC, abstractmethod

class Figura:
    def __init__(self, nombre):
        self.Nombre = nombre
        self.Area = None
        self.Volumen = None

class Plano(ABC):
    @abstractmethod
    def calcularArea(self):
        pass

class Circulo(Plano):
    def __init__(self, radio):
        self.radio = radio

    def calcularArea(self):
        self.Area = 3.1416 * (self.radio ** 2)
        return self.Area

class Rectangulo(Plano):
    def __init__(self, base, altura):
        self.Base = base
        self.Altura = altura

    def calcularArea(self):
        self.Area = self.Base * self.Altura
        return self.Area

class Tridimensional(ABC):
    @abstractmethod
    def calcularVolumen(self):
        pass

class Cubo(Tridimensional):
    def __init__(self, lado):
        self.Lado = lado

    def calcularVolumen(self):
        self.Volumen = self.Lado ** 3
        return self.Volumen

class Cilindro(Tridimensional):
    def __init__(self, radio, altura):
        self.Radio = radio
        self.Altura = altura

    def calcularVolumen(self):
        self.Volumen = 3.1416 * (self.Radio ** 2) * self.Altura
        return self.Volumen

# Ejemplo de uso
if __name__ == "__main__":
    # Crear objetos de las subclases
    circulo = Circulo(int(input("Ingrese el radio del círculo: ")))
    rectangulo = Rectangulo(int(input("Ingrese la base del rectángulo: ")), int(input("Ingrese la altura del rectángulo: ")))
    cubo = Cubo(int(input("Ingrese el lado del cubo: ")))
    cilindro = Cilindro(int(input("Ingrese el radio del cilindro: ")), int(input("Ingrese la altura del cilindro: ")))

    # Calcular áreas y volúmenes
    circulo.calcularArea()
    rectangulo.calcularArea()
    cubo.calcularVolumen()
    cilindro.calcularVolumen()

    # Mostrar resultados
    print(f"Área del círculo: {circulo.Area}")
    print(f"Área del rectángulo: {rectangulo.Area}")
    print(f"Volumen del cubo: {cubo.Volumen}")
    print(f"Volumen del cilindro: {cilindro.Volumen}")

